#!/usr/bin/env python3
"""Generated files of the standalone DSP modules: the FFT twiddle table (dsp/fft_twiddle_rom.sv) and the golden
vectors of their testbenches (sim/vectors/dsp_*.hex), all from `sadiy_ebaz.dspref`. Deterministic.

    python zynq-ebaz/rtl/dsp/gen_dsp.py [--check]
"""
from __future__ import annotations

import argparse
import math
import random
import sys
from pathlib import Path
from typing import Dict

HERE = Path(__file__).resolve().parent
REPO = HERE.parents[2]
sys.path[:0] = [str(REPO / "src"), str(REPO / "zynq-ebaz" / "sw")]

from sadiy_ebaz import dspref  # noqa: E402

VECTORS = HERE.parent / "sim" / "vectors"
M24, M18 = (1 << 24) - 1, (1 << 18) - 1

FFT_CASES = (  # logn, hann, signal
    dict(logn=6, hann=0, kind="tone"),
    dict(logn=10, hann=1, kind="two"),
    dict(logn=12, hann=0, kind="noise"),
    dict(logn=4, hann=1, kind="noise"),
)
FIR_CASES = (  # taps, decim, shift, samples
    dict(coef="gauss33", decim=4, shift=17, n=400),
    dict(coef="short", decim=1, shift=2, n=60),
)


def hexlines(values, digits: int) -> str:
    return "".join(f"{v:0{digits}X}\n" for v in values)


def twiddle_sv() -> str:
    rom = dspref.twiddle_rom()
    lines = ["// generated by rtl/dsp/gen_dsp.py from sadiy_ebaz.dspref.twiddle_rom(), do not edit.",
             "// {wr, wi} = round(131071 * (cos, -sin)(2 pi k / 4096)), k = 0 .. 2047; registered read.",
             "`default_nettype none", "module fft_twiddle_rom (", "  input  wire logic               clk,",
             "  input  wire logic [10:0]        addr,", "  output      logic signed [17:0] wr,",
             "  output      logic signed [17:0] wi", ");",
             '  (* rom_style = "block" *) logic [35:0] rom [0:2047];', "  initial begin"]
    lines += [f"    rom[{k}] = 36'h{((wr & M18) << 18) | (wi & M18):09X};" for k, (wr, wi) in enumerate(rom)]
    lines += ["  end", "  logic [35:0] q;", "  always_ff @(posedge clk) q <= rom[addr];",
              "  assign wr = $signed(q[35:18]);", "  assign wi = $signed(q[17:0]);", "endmodule",
              "`default_nettype wire", ""]
    return "\n".join(lines)


def fft_signal(case: dict, seed: int):
    n = 1 << case["logn"]
    rng = random.Random(seed)
    if case["kind"] == "tone":
        f = 5
        return ([int(3_000_000 * math.cos(2 * math.pi * f * i / n)) for i in range(n)],
                [int(3_000_000 * math.sin(2 * math.pi * f * i / n)) for i in range(n)])
    if case["kind"] == "two":                    # a real signal: a strong tone between two bins and a weak one
        re = [int(2_000_000 * math.cos(2 * math.pi * 100.5 * i / n) + 20_000 * math.cos(2 * math.pi * 300 * i / n))
              for i in range(n)]
        return re, [0] * n
    lim = 1 << 22
    return [rng.randint(-lim, lim) for _ in range(n)], [rng.randint(-lim, lim) for _ in range(n)]


def fir_coef(name: str):
    if name == "gauss33":
        return dspref.gaussian_taps(33, 0.1)
    return [-131072, 131071, 5, -7, 60000]       # extreme values: saturation with shift 2


def build_files() -> Dict[str, str]:
    files = {"../../dsp/fft_twiddle_rom.sv": twiddle_sv()}
    for k, case in enumerate(FFT_CASES):
        re, im = fft_signal(case, k + 1)
        yr, yi = dspref.fft_ref(re, im, case["logn"], bool(case["hann"]))
        files[f"dsp_fft{k}_in.hex"] = hexlines([((r & M24) << 24) | (i & M24) for r, i in zip(re, im)], 12)
        files[f"dsp_fft{k}_out.hex"] = hexlines([((r & M24) << 24) | (i & M24) for r, i in zip(yr, yi)], 12)
        files[f"dsp_fft{k}_meta.hex"] = hexlines([case["logn"], case["hann"]], 8)
    for k, case in enumerate(FIR_CASES):
        rng = random.Random(100 + k)
        coef = fir_coef(case["coef"])
        re = [rng.randint(-131072, 131071) for _ in range(case["n"])]
        im = [rng.randint(-131072, 131071) for _ in range(case["n"])]
        if k == 0:                               # a step in the middle: the filter's step response
            re[100:200] = [100000] * 100
        yr, yi = dspref.fir_ref(re, im, coef, case["decim"], case["shift"])
        files[f"dsp_fir{k}_coef.hex"] = hexlines([c & M18 for c in coef], 5)
        files[f"dsp_fir{k}_in.hex"] = hexlines([((r & M18) << 18) | (i & M18) for r, i in zip(re, im)], 9)
        files[f"dsp_fir{k}_out.hex"] = hexlines([((r & M18) << 18) | (i & M18) for r, i in zip(yr, yi)], 9)
        files[f"dsp_fir{k}_meta.hex"] = hexlines([len(coef), case["decim"], case["shift"], case["n"], len(yr)], 8)
    rng = random.Random(7)
    pairs = [(0, 0), (1, 0), (2047, -2048), (-8388608, -8388608), (8388607, 8388607), (1448, 1448)]
    pairs += [(rng.randint(-(1 << b), 1 << b), rng.randint(-(1 << b), 1 << b)) for b in range(1, 23) for _ in range(6)]
    files["dsp_pwr_in.hex"] = hexlines([((r & M24) << 24) | (i & M24) for r, i in pairs], 12)
    files["dsp_pwr_out.hex"] = hexlines([dspref.power_ref(r, i) for r, i in pairs], 7)
    files["dsp_pwr_meta.hex"] = hexlines([len(pairs)], 8)
    return files


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--check", action="store_true", help="write nothing; exit 1 if files on disk differ")
    args = ap.parse_args(argv)
    files = build_files()
    if args.check:
        stale = [n for n, text in files.items() if not (VECTORS / n).exists() or (VECTORS / n).read_text() != text]
        if stale:
            print("DSP files out of date: " + ", ".join(stale), file=sys.stderr)
            return 1
        print(f"DSP files current ({len(files)} files)")
        return 0
    for name, text in files.items():
        (VECTORS / name).write_text(text)
    print(f"wrote {len(files)} DSP files")
    return 0


if __name__ == "__main__":
    sys.exit(main())
